create or replace function public.ui_courses_decision_page(
 p_limit integer default 50,p_offset integer default 0,p_query text default null,p_country_code text default null,p_subdivision_code text default null,p_provider_id uuid default null,p_level_code text default null,p_field_code text default null,p_delivery_mode text default null,p_lifecycle_status text default null,p_publication_status text default null,p_has_fee boolean default null,p_has_intake boolean default null,p_has_english boolean default null,p_has_scholarship boolean default null,p_min_completeness numeric default null,p_freshness text default null,p_sort text default 'course',p_direction text default 'asc') returns jsonb language plpgsql stable security definer set search_path=public,catalogue,ref,search,scholarship,auth as $$
declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200);v_offset int:=greatest(coalesce(p_offset,0),0);v_sort text:=lower(coalesce(p_sort,'course'));v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
begin if auth.uid() is null then raise exception 'authentication required';end if;return(
with base as (
 select c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,sl.code level_code,sl.name level_name,fos.code field_code,fos.name field_of_study,c.delivery_mode,coalesce(d.completeness_score,0) completeness_score,
 exists(select 1 from catalogue.course_fees f where f.course_id=c.id) has_fee,
 exists(select 1 from catalogue.course_intakes i where i.course_id=c.id) has_intake,
 exists(select 1 from catalogue.course_english_requirements er where er.course_id=c.id) has_english,
 exists(select 1 from scholarship.scopes ss where ss.course_id=c.id and coalesce(ss.include_exclude,'include')='include') has_scholarship,
 (select count(*) from catalogue.course_campuses cc where cc.course_id=c.id) campus_count,
 coalesce(ps.code,ps2.code) subdivision_code,coalesce(ps.name,ps2.name) subdivision_name
 from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
 left join ref.study_levels sl on sl.id=c.study_level_id left join ref.fields_of_study fos on fos.id=c.primary_field_id left join search.course_documents d on d.course_id=c.id
 left join ref.subdivisions ps on ps.id=p.subdivision_id
 left join lateral (select s.code,s.name from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id join ref.subdivisions s on s.id=ca.subdivision_id where cc.course_id=c.id order by cc.is_primary desc nulls last limit 1) ps2 on true
 where (nullif(trim(coalesce(p_query,'')),'') is null or c.canonical_title ilike '%'||trim(p_query)||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%' or coalesce(c.course_code,'') ilike '%'||trim(p_query)||'%' or coalesce(c.stable_key,'') ilike '%'||trim(p_query)||'%')
 and (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
 and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or coalesce(ps.code,ps2.code)=upper(trim(p_subdivision_code)))
 and (p_provider_id is null or c.provider_id=p_provider_id)
 and (nullif(trim(coalesce(p_level_code,'')),'') is null or sl.code=trim(p_level_code))
 and (nullif(trim(coalesce(p_field_code,'')),'') is null or fos.code=trim(p_field_code))
 and (nullif(trim(coalesce(p_delivery_mode,'')),'') is null or c.delivery_mode=trim(p_delivery_mode))
 and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or c.lifecycle_status=trim(p_lifecycle_status))
 and (nullif(trim(coalesce(p_publication_status,'')),'') is null or c.publication_status=trim(p_publication_status))
),filtered as(select * from base where (p_has_fee is null or has_fee=p_has_fee) and (p_has_intake is null or has_intake=p_has_intake) and (p_has_english is null or has_english=p_has_english) and (p_has_scholarship is null or has_scholarship=p_has_scholarship) and (p_min_completeness is null or completeness_score>=p_min_completeness) and (nullif(trim(coalesce(p_freshness,'')),'') is null or (p_freshness='never_verified' and last_verified_at is null) or (p_freshness='modified_7d' and updated_at>=now()-interval '7 days') or (p_freshness='modified_30d' and updated_at>=now()-interval '30 days') or (p_freshness='stale_180d' and (last_verified_at is null or last_verified_at<now()-interval '180 days')))), numbered as(select *,count(*) over() total_count from filtered),ordered as(select * from numbered order by case when v_sort='course' and v_dir='asc' then lower(canonical_title) end asc,case when v_sort='course' and v_dir='desc' then lower(canonical_title) end desc,case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,case when v_sort='completeness' and v_dir='asc' then completeness_score end asc,case when v_sort='completeness' and v_dir='desc' then completeness_score end desc,case when v_sort='modified' and v_dir='asc' then updated_at end asc,case when v_sort='modified' and v_dir='desc' then updated_at end desc,case when v_sort='verified' and v_dir='asc' then last_verified_at end asc nulls first,case when v_sort='verified' and v_dir='desc' then last_verified_at end desc nulls last,lower(canonical_title),id limit v_limit offset v_offset)
select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) from ordered o);end$$;
revoke all on function public.ui_courses_decision_page(integer,integer,text,text,text,uuid,text,text,text,text,text,boolean,boolean,boolean,boolean,numeric,text,text,text) from public,anon;grant execute on function public.ui_courses_decision_page(integer,integer,text,text,text,uuid,text,text,text,text,text,boolean,boolean,boolean,boolean,numeric,text,text,text) to authenticated,service_role;

create or replace function public.ui_course_related_campuses(p_course_id uuid) returns jsonb language sql stable security definer set search_path=public,catalogue,ref,auth as $$select coalesce(jsonb_agg(jsonb_build_object('id',ca.id,'name',ca.name,'city',ca.city,'postcode',ca.postcode,'country_code',co.iso_alpha2,'subdivision_code',s.code,'subdivision_name',s.name,'delivery_mode',cc.delivery_mode,'is_primary',cc.is_primary,'website',ca.website) order by cc.is_primary desc nulls last,ca.name),'[]'::jsonb) from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id join ref.countries co on co.id=ca.country_id left join ref.subdivisions s on s.id=ca.subdivision_id where cc.course_id=p_course_id and auth.uid() is not null$$;
revoke all on function public.ui_course_related_campuses(uuid) from public,anon;grant execute on function public.ui_course_related_campuses(uuid) to authenticated,service_role;
